def _format_trace_value(value, maxlen):
    if maxlen <= 0:
        return ''

    # Get the string representation
    repr_str = bbrepr(value)

    # If it's already short enough, return it
    if len(repr_str) <= maxlen:
        return repr_str

    # If it's too long, truncate and add ellipsis
    # Try to leave room for ellipsis
    if maxlen > 3:
        # Leave space for '...'
        return repr_str[:maxlen-3] + '...'
    else:
        # Even if we can't show much, show what we can
        return repr_str[:maxlen]
